{"command":"@'
import json,re
from pathlib import Path
root=Path(r'C:\Users\edburns\workareas\dd-3061974-03-cargotracker-windows-shepherd-control\1-arrival-deadline-control-remove-before-merge\shepherd-tasks-e79d621c-3af9-4238-8f51-fde34dde1e94-20260910-1222')
for p in sorted(root.glob('phase*-task-*.jsonl')):
  failures=[]; usage=[]; model=[]
  for i,line in enumerate(p.open(encoding='utf-8'),1):
    o=json.loads(line)
    if o.get('type')=='tool.execution_complete' and not o.get('data',{}).get('success',True):
      d=o.get('data',{}); failures.append({'line':i,'tool':d.get('toolName') or d.get('name'),'error':str(d.get('error') or d.get('result') or d)[:180]})
    if o.get('type')=='session.usage_checkpoint': usage.append(o.get('data'))
    if o.get('type')=='model.call_finished':
      d=o.get('data',{}); keys={k:v for k,v in d.items() if 'token' in k.lower() or 'usage' in k.lower() or 'cost' in k.lower()};
      if keys:model.append(keys)
  print(json.dumps({'file':p.name,'failed_tools':failures,'usage':usage,'model_metric_samples':model[:2]},default=str))
'@ | python -","description":"Extract failures and usage checkpoints","initial_wait":30,"mode":"sync"}

