for p in sorted(root.glob('phase2-task-*.md')):
 s=p.read_text(encoding='utf-8')
 pairs=[]
 for pat in [r'\{"reviewId":(\d+).*?"commentCount":(\d+)',r'"reviewId"\s*:\s*(\d+).*?"commentCount"\s*:\s*(\d+)']:
  pairs += [(int(a),int(b)) for a,b in re.findall(pat,s,re.S)]
 unique={a:b for a,b in pairs}
 lines=[x.strip() for x in s.splitlines() if re.search(r'Comments generated|finding|no findings|review.*comment|Copilot review',x,re.I) and len(x)<500]
 print(json.dumps({'file':p.name,'reviews':unique,'evidence':lines[-20:]},ensure_ascii=False))
