import json
from pathlib import Path
root=Path(r'C:\Users\edburns\workareas\dd-3061974-03-cargotracker-windows-shepherd-control\1-arrival-deadline-control-remove-before-merge\shepherd-tasks-e79d621c-3af9-4238-8f51-fde34dde1e94-20260910-1222')
def walk(o,path='',out=None):
 out=out if out is not None else []
 if isinstance(o,dict):
  for k,v in o.items():
   p=f'{path}.{k}' if path else k
   if any(x in k.lower() for x in ('token','nanoaiu','premiumrequest','cost')) and not isinstance(v,(dict,list)): out.append((p,v))
   walk(v,p,out)
 elif isinstance(o,list):
  for i,v in enumerate(o): walk(v,f'{path}[]',out)
 return out
for p in sorted(root.glob('phase*-task-*.jsonl')):
 fails=[]; metrics={}
 for line in p.open(encoding='utf-8'):
  o=json.loads(line)
  if o.get('type')=='tool.execution_complete' and o.get('data',{}).get('success') is False:
   d=o['data']; fails.append((d.get('toolName'),d.get('errorCode'),str(d.get('resultContent') or d.get('error') or '')[:100]))
  if o.get('type')=='session.usage_checkpoint':
   for k,v in walk(o.get('data')): metrics[k]=v
 print(json.dumps({'file':p.name,'fail_count':len(fails),'failures':fails,'usage_metrics':metrics},default=str))
'@ | python -","description":"Summarize failures and credit metrics","initial_wait":30,"mode":"sync"}

