{"command":"@'
import json
from pathlib import Path
root=Path(r'C:\Users\edburns\workareas\dd-3061974-03-cargotracker-windows-shepherd-control\1-arrival-deadline-control-remove-before-merge\shepherd-tasks-e79d621c-3af9-4238-8f51-fde34dde1e94-20260910-1222')
tot=[]
for p in sorted(root.glob('*-otel-*.jsonl')):
 rec=[]
 for line in p.open(encoding='utf-8'):
  o=json.loads(line)
  if o.get('type')=='metric' and o.get('name')=='gen_ai.client.token.usage': rec.append(o)
 last=rec[-1]
 # discover histogram points recursively
 pts=[]
 def walk(x):
  if isinstance(x,dict):
   if 'sum' in x and 'count' in x and isinstance(x['sum'],(int,float)): pts.append((x['sum'],x['count']))
   for v in x.values(): walk(v)
  elif isinstance(x,list):
   for v in x: walk(v)
 walk(last)
 sums=sorted(set(pts))
 vals=sorted([x[0] for x in sums],reverse=True)[:2]
 inp=vals[0] if vals else 0; out=vals[1] if len(vals)>1 else 0
 tot.append((p.name,inp,out))
print(json.dumps({'files':[{'file':a,'input':b,'output':c} for a,b,c in tot],'total_input':sum(x[1] for x in tot),'total_output':sum(x[2] for x in tot)}))
'@ | python -","description":"Calculate token totals from OTEL","initial_wait":30,"mode":"sync"}

